<script setup>
import { ref, computed, watch, nextTick, onMounted, onBeforeUnmount } from 'vue';
import { useMissions, validateMissionForm } from './composables/useMissions';
import UiIcon from './components/UiIcon.vue';
import ResearchIllustration from './components/ResearchIllustration.vue';
const {
  account, walletError, connecting, busy, notice, activeView, search, activeCategory,
  selected, createOpen, guideOpen, mobileNav, txHash, missionForm, evidence, contribution,
  contributions, claimableAmount, walletBalance, configured, shortAccount, correctChain,
  topics, filtered, savedCount, sortBy, loading, loadError, contributionsLoading,
  contributionsError, statsLoading, statsError, txStatus, txError, activeTransaction,
  formErrors, selectedIsCreator, selectedIsOpen, selectedCanRefund, notify, saveMission,
  scrollTo, connectWallet, switchNetwork, openCreate, refreshMissions, loadContributions,
  transact, closeModal, isSaved, safeExternalUrl, explorerLink, resetFilters, refreshAll,
} = useMissions();
const logo = `${import.meta.env.BASE_URL}civiquill-mark.svg`;
const detailTab = ref('Brief'), createStep = ref(1), rewardsOpen = ref(false), dialog = ref(null);
const approvalAmounts = ref({}), approvingId = ref(null);
const mobileMedia = matchMedia('(max-width: 760px)'), isMobile = ref(mobileMedia.matches);
const modalOpen = computed(() => !!(selected.value || createOpen.value || guideOpen.value || rewardsOpen.value));
const modalTitle = computed(() => selected.value ? selected.value.title : createOpen.value ? 'Create a mission' : rewardsOpen.value ? 'Your rewards' : 'The Civiquill field guide');
const topicIcons = { 'All topics': 'grid', 'Tokenized assets': 'layers', Ecosystem: 'network', 'Market structure': 'chart', 'Risk research': 'shield' };
const topicColors = { 'Tokenized assets': 'sage', Ecosystem: 'lavender', 'Market structure': 'sand', 'Risk research': 'blue' };
const anyFilters = computed(() => !!search.value || activeCategory.value !== 'All topics');
const minimumDate = new Date(Date.now() + 60_000 - new Date().getTimezoneOffset() * 60_000).toISOString().slice(0, 16);
let previousFocus, navigationFocus;
function closeAll() { if (busy.value) { notify('Your transaction is still in progress. Follow its status here.'); return; } closeModal(); rewardsOpen.value = false; }
function resetTransactionFeedback() { if (!busy.value) { txError.value = ''; txHash.value = ''; txStatus.value = 'idle'; notice.value = ''; } }
function openDetails(m) { resetTransactionFeedback(); detailTab.value = 'Brief'; selected.value = m; }
function navigate(view) { activeView.value = view; mobileNav.value = false; scrollTo('missions'); }
function chooseTopic(topic) { activeCategory.value = topic; activeView.value = 'All missions'; mobileNav.value = false; scrollTo('missions'); }
function startCreate() { resetTransactionFeedback(); createStep.value = 1; mobileNav.value = false; openCreate(); }
function openGuide() { resetTransactionFeedback(); mobileNav.value = false; guideOpen.value = true; }
function openRewards() { resetTransactionFeedback(); mobileNav.value = false; rewardsOpen.value = true; }
function backToTop() { window.scrollTo({ top: 0, behavior: matchMedia('(prefers-reduced-motion: reduce)').matches ? 'instant' : 'smooth' }); }
function amountText(amount) { const value = Number(amount || 0); return value > 0 && value < 0.00001 ? '<0.00001' : value.toLocaleString('en-US', { maximumFractionDigits: 5 }); }
async function approveResearch(id) { approvingId.value = id; await transact('approve', id, approvalAmounts.value[id]); }
function updateMobile(event) { isMobile.value = event.matches; if (!event.matches) mobileNav.value = false; }
function handleNavigationKey(event) {
  if (!modalOpen.value && !mobileNav.value) return;
  if (event.key === 'Escape' && mobileNav.value) mobileNav.value = false;
  if (event.key !== 'Tab') return;
  const surface = modalOpen.value ? dialog.value : document.querySelector('.sidebar');
  const buttons = [...surface.querySelectorAll('a[href], button, input, select, textarea, [tabindex]')].filter(el => !el.disabled && el.tabIndex >= 0 && el.getClientRects().length);
  const first = buttons[0], last = buttons.at(-1);
  if (!first) { event.preventDefault(); return; }
  if (event.shiftKey && (document.activeElement === first || !surface.contains(document.activeElement))) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && (document.activeElement === last || !surface.contains(document.activeElement))) { event.preventDefault(); first.focus(); }
}
function reviewDraft() { const result = validateMissionForm(missionForm.value); formErrors.value = result.errors; if (!Object.keys(result.errors).length) createStep.value = 2; }
function downloadBrief() {
  const f = missionForm.value;
  const text = `# ${f.title || 'Untitled research mission'}\n\nCiviquill · ${f.category}\n\n## Research brief\n${f.description || 'Add scope, primary sources and acceptance criteria here.'}\n\n## Submission deadline\n${f.deadline || 'To be set'}\n\n## Reward pool\n${f.reward || '0'} testnet ETH\n\nPublished brief: ${f.uri || 'Add a public URL after hosting this file.'}\n\nThe mission creator reviews submissions. A submission does not guarantee a reward. Testnet ETH has no intended monetary value.\n`;
  const url = URL.createObjectURL(new Blob([text], { type: 'text/markdown;charset=utf-8' }));
  const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'civiquill-research-brief.md'; anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000); notify('Brief downloaded. Publish it, then add its public URL before funding your mission.');
}
watch(modalOpen, async (open) => {
  if (open) { previousFocus = document.activeElement; mobileNav.value = false; await nextTick(); dialog.value?.showModal(); document.body.style.overflow = 'hidden'; }
  else { dialog.value?.close(); document.body.style.overflow = ''; await nextTick(); if (previousFocus?.isConnected) previousFocus.focus(); }
});
watch(selected, (m, previous) => { if (m?.key !== previous?.key) { detailTab.value = 'Brief'; approvalAmounts.value = {}; } });
watch(mobileNav, async (open) => { document.body.style.overflow = open || modalOpen.value ? 'hidden' : ''; if (open) { navigationFocus = document.activeElement; await nextTick(); document.querySelector('.sidebar .brand')?.focus(); } else { await nextTick(); if (!modalOpen.value && navigationFocus?.isConnected) navigationFocus.focus(); } });
onMounted(() => { mobileMedia.addEventListener('change', updateMobile); document.addEventListener('keydown', handleNavigationKey); });
onBeforeUnmount(() => { document.body.style.overflow = ''; mobileMedia.removeEventListener('change', updateMobile); document.removeEventListener('keydown', handleNavigationKey); });
</script>

