    <div class="sidebar-bottom"><div class="sidebar-note"><UiIcon name="quill" :size="27"/><h3>Have a better question?</h3><p>Give it a brief.<br>Let curiosity do the rest.</p><button @click="startCreate">Create a mission<UiIcon name="plus" :size="16"/></button></div><button class="guide-link" @click="openGuide"><UiIcon name="book" :size="18"/>Contributor guide<UiIcon name="external" :size="14"/></button><div class="sidebar-status"><span class="status-dot"></span>Robinhood Chain<span>TESTNET</span></div></div>
  </aside>
