    <header class="topbar"><button class="icon-button mobile-menu" @click="mobileNav = !mobileNav" :aria-expanded="mobileNav" aria-label="Toggle navigation"><UiIcon :name="mobileNav ? 'close' : 'menu'"/></button><a class="mobile-brand" href="#" @click="backToTop" aria-label="Civiquill home">Civiquill.</a><div class="breadcrumb"><span>Workspace</span><UiIcon name="chevron" :size="13"/><strong>{{ activeView === 'All missions' ? 'Explore missions' : activeView === 'Saved' ? 'Saved missions' : 'My activity' }}</strong></div><div class="topbar-actions"><span class="network-pill"><span class="status-dot"></span>Robinhood Chain<span class="testnet-badge">TESTNET</span></span><button class="button wallet-button" :disabled="connecting" @click="account ? openRewards() : connectWallet()"><UiIcon name="wallet" :size="17"/><span>{{ connecting ? 'Connecting…' : shortAccount }}</span></button></div></header>
