          <div class="board-tabs" aria-label="Mission views"><button v-for="view in ['All missions', 'Saved', 'My activity']" :key="view" :class="{ active: activeView === view }" :aria-pressed="activeView === view" @click="activeView = view">{{ view }}<span v-if="view === 'Saved' && savedCount">{{ savedCount }}</span></button></div>
          <div class="board-tools"><label class="search-field"><UiIcon name="search" :size="18"/><input v-model="search" type="search" placeholder="A topic, a question, a rabbit hole…" aria-label="Search missions"/></label><label class="sort-field"><span class="sr-only">Sort missions</span><select v-model="sortBy"><option value="recommended">Recommended</option><option value="newest">Newest first</option><option value="reward">Highest reward</option><option value="deadline">Closing soon</option></select></label></div>
          <div class="filter-row" aria-label="Filter by topic"><button v-for="topic in topics" :key="topic" :class="{ active: activeCategory === topic }" :aria-pressed="activeCategory === topic" @click="activeCategory = topic">{{ topic }}</button></div>
          <div v-if="!configured" class="preview-notice"><UiIcon name="info" :size="16"/><p><strong>A place to explore.</strong> Sample briefs &amp; illustrative testnet rewards.</p><button @click="openGuide" aria-label="About the preview"><UiIcon name="arrow" :size="16"/></button></div>
